#define CI_ALWAYS_INLINE __attribute__((always_inline))
static float2 _affineTransform(float4x4 m, float2 p)
{
    return float2(dot(float3(p,1.0), m[0].xyz),
                  dot(float3(p,1.0), m[1].xyz));
}
