#ifdef __CIKERNEL_METAL_SUPPORTS_GATHER__ //[
    static half2 _gatherTransform(half2x2 m, half2 p)
    {
        return p * m + 0.5;
    }
    #define GATHER_COORD_TO_IDX(p) short(p.x + p.y * 2)
    template <typename T>
    static T _gatherOrdered(float4x4 m, T v)
    {
        // reorder samples into linear buffer based on Metal's specified order of gathered samples:v[0] v[1]
        v = v.wzxy; //                                                                              v[2] v[3]
        // reduce transform to orientation matrix for unit extent of [-0.5 -0.5 1 1], centered about the origin
        half2x2 orientation = half2x2(sign(m[0][0]),sign(m[0][1]),
                                      sign(m[1][0]),sign(m[1][1]));
        // transform gather coords based on sampler transform
        half2 p00 = _gatherTransform(orientation, half2(-0.5,-0.5));
        half2 p10 = _gatherTransform(orientation, half2( 0.5,-0.5));
        half2 p11 = _gatherTransform(orientation, half2( 0.5, 0.5));
        half2 p01 = _gatherTransform(orientation, half2(-0.5, 0.5));
        // convert gather coords to buffer indices, and return samples in CCW order starting w/ sample at the lower left
        return T(v[GATHER_COORD_TO_IDX(p00)],
                 v[GATHER_COORD_TO_IDX(p10)],
                 v[GATHER_COORD_TO_IDX(p11)],
                 v[GATHER_COORD_TO_IDX(p01)]);
    }
#endif //] __CIKERNEL_METAL_SUPPORTS_GATHER__
