        // Writes 4 color values to the destination texture for the current 2x2 group of pixels.
        void destination::write(float4 v0, float4 v1, float4 v2, float4 v3)
        {
#if __CIKERNEL_SUPPORTS_VARIABLE_GROUPSIZE__
            float4x4 v = float4x4(v0, v1, v2, v3);
            for (short i = 0; i < 4; i++)
            {
                short dx = i % short(KERNEL_OUTPUT_SIZE(m).x);
                short dy = i / short(KERNEL_OUTPUT_SIZE(m).y);
                _destinationWrite(t, m, r, v[i], c + float2(dx,dy));
            }
#else
            _destinationWrite(t, m, r, v0, c);
            _destinationWrite(t, m, r, v1, c + float2(1,0));
            _destinationWrite(t, m, r, v2, c + float2(0,1));
            _destinationWrite(t, m, r, v3, c + float2(1,1));
#endif
        }
