    float4 unpremultiply(float4 s) { return float4(s.xyz/ fmax(s.w, 0.00001), s.w); }
    half4 unpremultiply(half4 s) { return half4(s.xyz/ fmax(s.w, 0.0001h), s.w); }
    #define _srgb_to_linear(s,t) sign(s) * mix(abs(s)*0.077399380804954##t, pow(abs(s)*0.947867298578199##t + 0.052132701421801##t, 2.4##t), step(0.04045##t, abs(s)))
    float3 srgb_to_linear(float3 s) { return _srgb_to_linear(s, f); }
    half3 srgb_to_linear(half3 s) { return _srgb_to_linear(s, h); }
    float4 srgb_to_linear(float4 s)
    {
        s = float4(unpremultiply(s));
        s.rgb = _srgb_to_linear(s.rgb, f);
        return premultiply(s);
    }
    half4 srgb_to_linear(half4 s)
    {
        s = half4(unpremultiply(s));
        s.rgb = _srgb_to_linear(s.rgb, h);
        return premultiply(s);
    }
    #define _linear_to_srgb(s,t) sign(s) * mix(abs(s)*12.92##t, pow(abs(s), 0.4166667##t) * 1.055##t - 0.055##t, step(0.0031308##t, abs(s)))
